    int n, i, a[1005], lo, hi;
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    min_max(a, n, &lo, &hi);
    printf("%d %d\n", lo, hi);
    return 0;
}

