#include <stdio.h>
struct Complex { int re, im; };
struct Complex add(struct Complex x, struct Complex y) {
    struct Complex r = {x.re + y.re, x.im + y.im};
    return r;
}
struct Complex mul(struct Complex x, struct Complex y) {
    struct Complex r = {x.re * y.re - x.im * y.im, x.re * y.im + x.im * y.re};
    return r;
}
void print_complex(struct Complex c) {
    if (c.im < 0) printf("%d-%di\n", c.re, -c.im);
    else printf("%d+%di\n", c.re, c.im);
}
int main(void) {
    struct Complex x, y;
    scanf("%d %d %d %d", &x.re, &x.im, &y.re, &y.im);
    print_complex(add(x, y));
    print_complex(mul(x, y));
    return 0;
}

